679	  public useBodyParser(
680	    type: string | string[] | RegExp,
681	    rawBody: boolean,
682	    options?: NestFastifyBodyParserOptions,
683	    parser?: FastifyBodyParser<Buffer, TServer>,
684	  ) {
685	    const parserOptions = {
686	      ...(options || {}),
687	      parseAs: 'buffer' as const,
688	    };
689	
690	    this.getInstance().addContentTypeParser<Buffer>(
691	      type,
692	      parserOptions,
693	      (
694	        req: RawBodyRequest<FastifyRequest<any, TServer, TRawRequest>>,
695	        body: Buffer,
696	        done,
697	      ) => {
698	        if (rawBody === true && Buffer.isBuffer(body)) {
699	          req.rawBody = body;
700	        }
701	
702	        if (parser) {
703	          parser(req, body, done);
704	          return;
705	        }
706	
707	        done(null, body);
708	      },
709	    );
710	
711	    // To avoid the Nest application init to override our custom
712	    // body parser, we mark the parsers as registered.
713	    this._isParserRegistered = true;
714	  }
