import { Controller, INestApplication, Module, Post } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as net from 'net';

let echoCount = 0;

@Controller()
class EchoController {
  @Post('echo')
  echo() {
    echoCount++;
    return 'echoed';
  }
}

@Module({
  controllers: [EchoController],
})
class EchoModule {}

describe('Graceful Shutdown (Fastify) - partial body', () => {
  let app: INestApplication;

  afterEach(async () => {
    if (app) {
      await app.close();
    }
  });

  it('should not run the handler for a request whose body completes after shutdown began', async () => {
    echoCount = 0;
    app = await NestFactory.create<NestFastifyApplication>(
      EchoModule,
      new FastifyAdapter(),
      { return503OnClosing: true, logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const socket = net.connect(port, '127.0.0.1');
    await new Promise(resolve => socket.on('connect', resolve));

    const body = '{"hello":"world"}';
    const firstChunk = body.slice(0, 5);
    const rest = body.slice(5);

    let rawResponse = '';
    socket.on('data', d => (rawResponse += d.toString()));

    // Send headers + first body chunk only
    socket.write(
      `POST /echo HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: ${body.length}\r\n\r\n${firstChunk}`,
    );
    await new Promise(r => setTimeout(r, 100));

    // Begin shutdown while the body is incomplete
    const closePromise = app.close();
    await new Promise(r => setTimeout(r, 50));

    // Now send the rest of the body
    socket.write(rest);

    // Wait for a response (or socket close)
    const closed = await Promise.race([
      new Promise<'closed'>(resolve => socket.on('close', () => resolve('closed'))),
      new Promise<'timeout'>(resolve => setTimeout(() => resolve('timeout'), 3000)),
    ]);

    console.log('closed:', closed);
    console.log('rawResponse:', JSON.stringify(rawResponse));
    console.log('echoCount:', echoCount);

    expect(echoCount).toBe(0);
    socket.destroy();
    await closePromise;
  }, 10000);
});

